export const BUILTIN_GENRE_PROFILES: BuiltinGenreProfile[] = [
  { id: "genre_fantasy_root", profileJson: "{\"positioning\":\"以架空异界为舞台，以超凡力量（魔法、神力、奥术、斗气等）与异族文明为依托，讲述主角探索未知秘境、完成力量跃迁并最终重塑世界秩序的冒险与史诗题材。\",\"sellingPoint\":\"世界奇观与异域生态的探索探索感；自洽严密的超凡体系（如魔药序列、奥术研究、位阶神格）带来的阶梯式成长快感；凡人以智慧或金手指打破古老神明、贵族垄断的降维逆袭爽点。\",\"coreConflict\":\"凡人微末个体与既定宿命、至高神权或阶级壁垒的抗争；未知旧神/深渊污染对文明的侵蚀与反侵蚀；不同超凡学派与种族阵营之间的生死道途争端。\",\"readerExpectation\":\"严密自洽的超凡法则与逻辑推演；新颖宏大且具有沉浸感的世界观构建；主角智商在线、目的明确，拒绝战力失衡与无逻辑的机械降神。\",\"classicStructure\":\"底层/穿越者开局并绑定异质核心（解决生存危机）→ 步入超凡组织（法师塔/教会/学院，解析力量本质并跨阶扬名）→ 卷入区域动荡与遗迹探秘（揭露世界暗面与古神伏笔）→ 跨位面争霸或抵抗灭世天灾（登临神座/重订法则）。\",\"worldSetting\":\"多位面与多元种族（人类、巨龙、精灵、魔物）并存的世界；涵盖魔导科技、古神遗迹、宏伟浮空城、深渊裂隙与神圣教廷；规则通常被以太、魔网、神明意志或不可名状的权柄所支配。\",\"typicalCharacters\":\"主角多为探求真理的求道型法师、背负秘密的破局者或猎魔骑士；配角搭配引路人式的渊博导师、理念对立的狂信徒宿敌、性格鲜明的异族伙伴，以及隐于历史深渊的不可直视之存在。\",\"pacingAdvice\":\"前3章确立生存困境与核心金手指机制，前30万字完成首轮力量质变与新手地图破局；以“危机预警-探寻线索-秘境攻坚-位阶进阶-世界观展开”为中循环，每10-15万字完成一次重大阶级破局，后期加速史诗感收拢。\",\"representativeWorks\":\"《诡秘之主》、 《盘龙》、 《奥术神座》、 《放开那个女巫》、 《巫界术士》\",\"commonPitfalls\":\"开篇大段说明文堆砌世界观导致节奏拖沓；刻意模仿生硬译制腔造成阅读门槛；力量体系后期通胀崩溃无法圆场；主角动机薄弱沦为被主线推着走的提线木偶。\"}" },
  { id: "genre_fantasy_eastern", profileJson: "{\"positioning\":\"以东方文化、武道神魔为骨骼，通过阶梯式修炼体系与世家宗门争锋，展现个体逆境崛起、斩破宿命并最终问鼎寰宇的热血幻想史诗。\",\"sellingPoint\":\"境界突破带来的确定性成长快感；越级反杀与底牌层出不穷的强爽感；从小城家族到大千世界的宏大探索欲；少年意气对抗强权垄断的极致宣泄。\",\"coreConflict\":\"草根修士的生存成长与上位阶层对修炼资源的绝对垄断之间的阶级冲突；宗门、帝统之间的气运道统之争；个体超脱与天地浩劫、纪元轮回的存亡对抗。\",\"readerExpectation\":\"严密不崩的战力阶梯；主角杀伐果断、智勇双全且不圣母；反击打脸顺畅不憋屈、尊严与地位实打实地靠战力夺回；宏大苍凉的东方神话史诗感。\",\"classicStructure\":\"开局遭逢变故或资质受限，偶得逆天机缘（功法/器物）打破僵局，在家族/小城争霸中崭露头角；中期拜入大宗门或卷入古国争雄，经由秘境夺宝与宗门大比声名鹊起；后期跨域换图，直面远古大能、禁区黑手与纪元危机，终成万界至尊。\",\"worldSetting\":\"天地以灵气或元力为根基，划分为清晰的等级关卡；空间多为“凡界-灵界-神荒”多层箱庭递进；盘踞着传承万载的荒古世家、不朽宗门与神朝，存在生灵禁区与古战场，遵循弱肉强食的丛林法则。\",\"typicalCharacters\":\"坚毅冷静、有仇必报的主角；身负神秘血脉或古老宿命的中期离去型白月光女主；护短的大能师尊或残魂老爷爷；插科打诨但关键时刻可靠的灵宠兄弟；打了小的来老的高傲世家反派。\",\"pacingAdvice\":\"3至5章安排一次小交锋或装逼反馈，10至15章完成一次秘境清算或小境界突破，30至50章完成一次大境界晋升与区域终极清算；换地图前务必彻底变现原有声望与战利品，避免长期受压抑。\",\"representativeWorks\":\"《斗破苍穹》、 《武动乾坤》、 《遮天》、 《完美世界》、 《牧神记》\",\"commonPitfalls\":\"境界通胀过快导致前期设定作废；换新地图后机械复刻“受辱-打脸”套路导致审美疲劳；女主沦为反复被抓的工具人引起读者烦躁；为爽而爽导致主角行径酷似反派失去共情基础。\"}" },
  { id: "genre_fantasy_western", profileJson: "{\"positioning\":\"以欧洲中世纪风貌与托尔金/DND体系为底色，围绕剑与魔法、神魔种族与奥术真理展开的个人史诗成长与世界探索传奇。\",\"sellingPoint\":\"严密自洽的超凡进阶体系（如奥术解析、血脉觉醒、神格铸造）；古典浓郁的异域奇幻氛围与多元种族生态；从小人物/边缘学徒逆袭为传奇强者、甚至弑神登顶的史诗成就感。\",\"coreConflict\":\"真理求索者与神明信仰的哲学冲突、凡人文明与深渊/天灾/异族的生存阵营战，以及世俗贵族王权与超凡教会/学派组织之间的权力博弈。\",\"readerExpectation\":\"原汁原味的西幻质感与奇观描写（巨龙、精灵、魔导科技、多元位面）；逻辑严密的施法与战斗设定，杜绝空洞的数值对轰；宏大而不失细节的冒险探索与阶层跨越。\",\"classicStructure\":\"边陲小镇/底层学徒开局获得特殊传承或金手指；通过冒险者委托、遗迹探索或学院考核完成超凡第一步；中期卷入王国政争或抵御魔潮危机，建立自身势力与领地；后期涉足诸神权柄、位面远征，最终打破旧神垄断或平息世界浩劫。\",\"worldSetting\":\"多层次的多元宇宙架构（主物质位面、深渊、星界、神国等）；诸神真实存在并垂赐神术，魔网或以太能量弥漫世间；存在剑士、骑士、游侠、法师等成熟职业工会与古老教廷。\",\"typicalCharacters\":\"主角常为兼具理智与决断的学者型施法者或具备禁忌血脉的孤狼战士；核心配角包括性格耿直的盾战士、高傲优雅的精灵射手、神秘老牌法师导师、背负救世宿命的落魄圣女与贪婪机敏的地精商人。\",\"pacingAdvice\":\"前期以具体的技能学习、装备打造和低阶位突破维持高频正向反馈；中期通过遗迹探险与领地建设交替推进，实现个人武力与社会地位双线跃迁；后期降低升级频率，转为大兵团神术战争与宏大规则对抗，确保决战的高压与爆发力。\",\"representativeWorks\":\"《恶魔法则》、顿《奥术神座》、顿《盘龙》、顿《巫界术士》、顿《巫师之旅》、顿《亵渎》\",\"commonPitfalls\":\"开局抛出大量设定集与诸神编年史导致阅读门槛过高；翻译腔过重或刻意拗口的人名地名造成审美疲劳；披着西幻皮写纯东方玄幻打脸套路，丧失西幻特有的职业协同与力量逻辑；过早引出神级战力导致中后期战力通胀崩坏。\"}" },
  { id: "genre_fantasy_xianxia", profileJson: "{\"positioning\":\"以凡人逆天改命、求取长生超脱为核心动力的东方古典幻想题材，兼具资源争夺的现实残酷与求索大道的情怀宿命。\",\"sellingPoint\":\"境界晋升带来的位阶质变与寿命增长；杀人夺宝、探索秘境的丰厚战利品正反馈；底牌层出、算计周密的越阶反杀；从底层蝼蚁一步步攀升至俯瞰诸天的阶级跨越感。\",\"coreConflict\":\"天地间有限的修真资源（灵脉、丹药、功法、机缘）与修士无限膨胀的求生欲之间的零和博弈；冰冷无情的宗门/天道规则与修士自我道心之间的抗衡。\",\"readerExpectation\":\"严密有序的境界与战力体系；主角心智成熟、杀伐果断、绝不圣母；每次历经凶险后都有明确且对等的实力/地位收益；换地图后依然保持合理的战力逻辑与新奇感。\",\"classicStructure\":\"微末出身获特殊机缘（小绿瓶/残魂/金手指）→ 宗门底层隐忍发育与摸底规则 → 秘境试炼夺宝并结下死仇 → 宗门大比或大劫降临一战扬名 → 被迫逃亡或破境飞升开启新地图 → 接触天地因果与古老秘辛 → 斩道登顶成就真仙/道祖。\",\"worldSetting\":\"多维立体的多层界域体系（下界凡尘、修真灵界、缥缈仙界）；崇尚丛林法则与实力至上，遍布洞天福地、凶险古迹与魔渊禁区；仙凡两隔，因果循环，天劫与道心誓言构成天道刚性约束。\",\"typicalCharacters\":\"主角多为稳健谨慎、心黑手狠但有底线的求道者；配角包括城府深沉的老谋深算长老、恃才傲物的修仙世家天骄、利益驱动的同盟道友、亦师亦友的伴生残魂或妖宠。\",\"pacingAdvice\":\"小境界两到三万字一次小高潮（突破或除敌），大境界十到十五万字完成一次质变积累（寻药、炼丹、渡劫）；前期重在资源获取与个人求生，中后期重在天地法则感悟与势力布局，严禁长时间无修为精进的日常水文。\",\"representativeWorks\":\"《凡人修仙传》、 《仙逆》、 《遮天》、 《大道争锋》、 《赤心巡天》\",\"commonPitfalls\":\"境界通货膨胀导致战力崩坏（如元婴满地走、金丹不如狗）；主角伪果断真圣母，频繁给仇人留生机引发后患；无脑堆砌招式名和玄学词汇导致打斗枯燥；过度依赖换地图导致前期人物与情感完全断层。\"}" },
  { id: "genre_fantasy_high_martial", profileJson: "{\"positioning\":\"以肉身气血或武道真意为基石、破坏力直达毁天灭地的升级流重度玄幻，主打以力破巧与阶层横推。\",\"sellingPoint\":\"兼具肉身近战拳拳到肉的打击感与碎星断岳的宏大破坏力；极度直观的境界质变与数值碾压；打破世家或神魔对武道资源垄断的阶层逆袭爽感。\",\"coreConflict\":\"底层武者对功法、气血药剂与天地资源的生存争夺，与上位阶层（世家、圣地、外域邪神）残酷垄断压迫之间的不可调和矛盾。\",\"readerExpectation\":\"战斗必须纯粹干脆、以力服人，绝不搞圣母退让；境界突破必须带来脱胎换骨的破坏力质变；天骄争霸与跨阶逆伐时，必须有强烈的同辈碾压与高层震惊反馈。\",\"classicStructure\":\"开局微末淬体（气血亏空/资质平平+破局金手指）→ 武考/宗门大比一鸣惊人打脸特权阶层 → 进入更高平台（圣地/军部/天骄训练营）并解锁武道真意 → 遭遇禁区动乱或外族异兽入侵成为前线砥柱 → 换大地图（星空/上界）肉身证道斩杀神魔。\",\"worldSetting\":\"高密度能量压制下的严酷世界（高武都市、玄幻皇朝或大荒异界），遍布危险禁区与异族裂缝；社会阶层以武道境界严格分级，崇尚纯粹的丛林法则与力量至上主义。\",\"typicalCharacters\":\"主角多为目标极度明确、杀伐果断的苦修武痴；反派多为恃强凌弱的世家二世祖、视众生为资粮的腐朽老怪；配角标配护短且身负暗伤的引路宗师、并肩厮杀的热血同袍与提供情报资源的商贾后代。\",\"pacingAdvice\":\"3至5章安排一次气血/战力测试或局部冲突展示压倒性实力；15至20章完成一次大境界突破或擂台登顶；每次换地图前必须有横扫本界域老一代强者的清场大高潮；严格控制战力膨胀系数，确保战斗细节不被抽象法术对轰取代。\",\"representativeWorks\":\"《全球高武》、 《高武纪元》、 《武极天下》、 《武炼巅峰》、 《沧元图》\",\"commonPitfalls\":\"中后期丢弃武道本质变成平庸的对波修仙，失去拳肉搏杀与战法技巧的临场感；战力膨胀过快导致前期苦修功法直接沦为废纸；主角缺乏危机驱动，被迫推着走导致爽感钝化；资源数值严重通胀使升级缺乏实感。\"}" },
  { id: "genre_urban_root", profileJson: "{\"positioning\":\"以现代都市文明为舞台，聚焦普通人获取超常能力、前沿信息或金手指后，跨越社会阶层、收割财富名望、改写人生命运的现实代入型题材。\",\"sellingPoint\":\"极高时代代入感下的阶层飞跃；信息差与特殊能力带来的降维打击与即时打脸；现实欲望（财富自由、社会地位、顶层人脉、红颜青睐）的极速兑现。\",\"coreConflict\":\"底层草根生存困境与资本权贵阶层壁垒的对抗；主角超前认知/非凡能力与世俗社会规则、行业潜规则的碰撞；新贵势力在资源争夺中对既得利益集团的颠覆。\",\"readerExpectation\":\"现实委屈与窝囊感的极速宣泄与强力反弹；合乎情理但超出常理的暴富或显圣体验；看着原本高不可攀的权贵、资本在主角面前低头俯首的绝对掌控感。\",\"classicStructure\":\"开篇陷入现实死局（失业、背叛、重病、债务）→ 觉醒核心外挂/获得转机 → 闪电解决眼前危机并完成资本积累/初步打脸 → 跨入更高社会圈层引来更强对手 → 多线经营实业/人脉/暗面势力逐步蚕食敌对势力 → 成为都市无冕之王或行业巨擘。\",\"worldSetting\":\"现代都市写字楼、高档会所、名利宴会、城中村及地下交易场所；规则受限于现代法律秩序与世俗道德，但在暗流涌动中极度崇尚资本支配、权力层级与人情世故。\",\"typicalCharacters\":\"主角（清醒利己、执行力极强、善于利用信息差的翻盘者）；反派（狗眼看人低的门童亲戚、骄横跋扈的纨绔二代、城府极深的幕后资本巨鳄）；配角（急需主角解决危局的豪门掌舵人/绝色女总裁、忠心耿耿的办事白手套）。\",\"pacingAdvice\":\"前三章必须完成‘遭遇压迫-获得破局能力-完成首轮变现/反击’的闭环；3-5章一个小爽点（利益兑现或认知打脸），15-20章完成一次圈层更替与资产量级跃迁；绝不能压抑主角超过两章，战力/财富数值膨胀要与社会影响力的反馈严格匹配。\",\"representativeWorks\":\"《黄金瞳》、 《重生之出人头地》、 《我真没想重生啊》、 《余罪》、 《重生之都市修仙》\",\"commonPitfalls\":\"现实逻辑过度悬浮（法治社会写出毫无后果的公然打杀，导致出戏）；反派脸谱化且智商强行归零（无限重复‘嘲讽-被打脸-喊人-再被打脸’的低级套路）；金钱与权力数值极速贬值失去购买力参照物；主角在获得优势后行事过于油腻、双标或戾气过重招致读者厌恶。\"}" },
  { id: "genre_urban_superpower", profileJson: "{\"positioning\":\"以现代繁华都市为表层依托、暗流涌动的超自然力量为内核，兼具都市生活爽感与超凡升级博弈的强幻想题材。\",\"sellingPoint\":\"超凡能力对世俗维度的降维打击；表里世界信息差带来的掌控感与扮猪吃虎；异能觉醒带来的阶层跃迁与超现实装逼反馈；新奇能力机制的开发与克制智斗。\",\"coreConflict\":\"个体觉醒超能与世俗既定规则/官方监管机构的摩擦；守护日常平静生活与卷入里世界残酷厮杀的拉扯；民间野性异能者与垄断超凡资源的财阀/邪恶组织的对抗。\",\"readerExpectation\":\"极强的生活代入感与超凡幻想的双重满足；在熟悉的生活场景中打脸特权阶级；清晰且惊艳的异能机制，以及主角在危机时刻掉马甲时引发的群体震惊与崇拜。\",\"classicStructure\":\"开局机缘觉醒特异功能，解决身边紧迫危机（职场/校园/家庭打脸）；顺藤摸瓜接触地下超凡圈子或官方特勤组织，完成从表世界向里世界的过渡；中期参与异能者联赛、争夺天材地宝或侦破异能犯罪，实力稳步提升；后期对抗颠覆世界秩序的恐怖组织或异界降临，确立顶尖霸主地位。\",\"worldSetting\":\"双轨制表里世界：表层是高楼林立、科技发达但遵循现代法律的世俗社会；底层是灵气复苏或基因突变催生的异能黑市、隐世世家与特工机构；普遍存在一套‘超凡力量不得暴露于世俗公众’的隐秘协议或记忆消除机制。\",\"typicalCharacters\":\"主角多为表面人畜无害（学生、社畜、典当行伙计）实则身怀禁忌能力的控场者；标配包括引路或负责监视的冷酷官方御姐、负责提供情报与搞笑的死党胖子、需要主角保护的世俗豪门大小姐；反派常为行事极端的堕落异能罪犯、视人命为草芥的境外财阀势力。\",\"pacingAdvice\":\"前3章必须让主角完成初次异能觉醒并解决一场现实微型危机；每5-8章安排一次异能应用或小规模世俗打脸；每15-20章进行一次里世界的生死搏杀或等级考核突破；切忌通篇纯打斗，必须在超凡战斗与都市日常（搞钱、社交、享受特权）之间张弛交替，保持都市生活气息。\",\"representativeWorks\":\"《隐杀》、 《大王饶命》、 《黄金瞳》、 《全职法师》、 《龙王传说》\",\"commonPitfalls\":\"力量体系膨胀失控，动辄毁天灭地导致现代都市背景彻底沦为摆设；过度弱智化官方组织与军队热武器，破坏世界观逻辑合理性；异能设定缺乏规则限制与代价机制，战斗变成纯唯心口胡；丧失‘现代人思维’，将都市异能写成换皮无脑玄幻宗门争斗。\"}" },
  { id: "genre_urban_workplace", profileJson: "{\"positioning\":\"立足现代真实行业生态，以底层打工人技能破局、职级攀升、权力与利益博弈为主线的现实感都市逆袭文。\",\"sellingPoint\":\"专业硬核实操带来的降维打击感；看透并反制职场潜规则、手撕甩锅甩烂摊子上司的宣泄感；从边缘螺丝钉到手握话语权的阶层跃迁爽感。\",\"coreConflict\":\"个体上升诉求与官僚体制壁垒的冲突，派系斗争中的站队与利益再分配，专业底线与商业潜规则之间的妥协与抗争。\",\"readerExpectation\":\"扎实可信的行业内幕与运作逻辑，情商与专业双在线的主角，绝不受委屈的精准反击，以及每一分付出都能换来职级、权力、收入的确定性回报。\",\"classicStructure\":\"开局背锅被裁或边缘化困境→凭借独门技术/信息差力挽狂澜拿下关键业务→晋升中层卷入高层派系斗争借力打力→掌控核心资源成为行业巨头或自立门户。\",\"worldSetting\":\"一线都市CBD写字楼、高精尖产业园或特定行业场景（如大厂、投行、律所、三甲医院），充斥着KPI考核、层级森严、资源内卷的丛林法则社会。\",\"typicalCharacters\":\"主角是技术过硬且深谙人情世故的破局者；配角包括贪功甩锅的顶头上司、见风使舵的心机同事、受制于人的佛系老员工以及暗中权衡的大老板。\",\"pacingAdvice\":\"3至5章化解一次小型穿小鞋或工作危机；15至20章拿下核心大项目或完成一次职级评定；40章左右完成一次职权换届或派系清算，确保“打脸-升职-加薪”正反馈链条不断裂。\",\"representativeWorks\":\"《猎头局中局》、都市行业文《大医凌然》、硬核商战向《大国重工》、职场博弈向《商海争锋》\",\"commonPitfalls\":\"行业知识缺乏调研导致常识性硬伤；反派行事全凭无脑嫉妒降智如同泼妇骂街；主角完全不讲人情世故纯靠蛮干爽文开挂；过早脱离具体业务转向无聊的悬浮商战或恋爱后宫。\"}" },
  { id: "genre_urban_life", profileJson: "{\"positioning\":\"立足当代社会市井烟火，聚焦家庭伦理、邻里关系、小本日常经营与平凡生活改善的写实温情向都市小说。\",\"sellingPoint\":\"极具代入感的市井烟火气，一步一个脚印摆脱贫困、改善家庭条件的踏实积累感，收拾极品亲邻的解气打脸，以及家人互助、邻里温情带来的治愈爽感。\",\"coreConflict\":\"小人物对体面、富足与和睦生活的追求，与拮据的经济现实、复杂的家庭矛盾、市井邻里的算计摩擦之间的拉扯与解决。\",\"readerExpectation\":\"扎实可信的生活细节与时代质感；日子越过越红火的确定性阶梯回报；家庭内部由隔阂走向理解的温情共鸣；对挑刺找茬的亲戚邻居进行合情合理的反击与震慑，拒绝窝囊受气。\",\"classicStructure\":\"开篇陷入现实困境（背债、下岗、家庭矛盾）并抓住微小转机（传承手艺、小金手指、特殊技能或重生信息差）；中期从小本生意（早餐摊、修家电、小饭馆等）切入，一边赚取第一桶金改善住房与生活，一边处理邻里琐事树立威望；后期扩大经营规模，盘活周边人脉，成为社区名流或行业翘楚，收获家庭和睦与社会地位。\",\"worldSetting\":\"千禧年至今的中国城镇、老旧小区、城中村或城乡接合部，常驻场景包括杂货铺、菜市场、特色小餐馆、临街商铺、老式居民楼院落等充满人情味与喧嚣感的日常场所。\",\"typicalCharacters\":\"主角多为务实沉稳、懂手艺或深谙人情世故的小人物；常备配角包括嘴碎但心软的父母长辈、爱占便宜嫉妒心强的极品亲戚邻居、形形色色的底层食客或顾客、以及性格温婉或并肩打拼的贤惠伴侣。\",\"pacingAdvice\":\"以“日常微小进展+小额收益正反馈”为日常节拍，3至5章展现一次生活改善或经营小高潮，8至12章化解一次邻里或家庭矛盾；严格控制财富膨胀速度，避免过早脱离市井生活，保持平缓爬升的幸福感曲线。\",\"representativeWorks\":\"《美食供应商》、 《生活系游戏》、 《俗人回档》、 《我真没想重生啊》\",\"commonPitfalls\":\"中后期财富极速膨胀脱离市井底色，沦为悬浮的跨国商战或都市异能；极品亲友刻画过于脸谱化且反复横跳挑衅，让读者感到憋屈恶心；过度流水账而缺乏阶段性经营目标与戏剧张力；强加出轨、绝症等家庭狗血纠纷破坏温馨治愈基调。\"}" },
  { id: "genre_history_root", profileJson: "{\"positioning\":\"以真实历史朝代或拟真架空封建王朝为舞台，主角携现代认知或超前眼界入局，在封建制度束缚与历史车轮下求存、崛起乃至改写历史轨迹的宏大演义。\",\"sellingPoint\":\"知识降维打击的快感（科技、战术、治国理念领先千年的碾压）；弥补历史遗憾、逆转民族悲剧的家国情怀；收服历史名臣良将、与顶级政客博弈的智商爽感；从小人物到封王拜相乃至取而代之的阶级跃升。\",\"coreConflict\":\"现代先进思想与封建宗法皇权体系的剧烈碰撞；主角推行改革或图谋崛起的野心，与既得利益集团（门阀、宦官、勋贵、外戚）、异族入侵以及历史宿命大势之间的生死抗衡。\",\"readerExpectation\":\"扎实的历史厚重感与细节考据（官制、礼法、器物不出戏）；古人具备符合历史地位的智商与城府；关键历史节点上的力挽狂澜（如挽救崖山、挽救明末）；合理的种田攀科技与合乎政治逻辑的夺权流程。\",\"classicStructure\":\"开局微末破局（寒门、濒死罪奴、落魄败家子，靠做生意或展现小才华解决眼前生存杀机）→ 地方立足与积累资本（科举中第、经营庄园或积累战功，建立核心班底与经济基础）→ 卷入中枢权力漩涡（参与夺嫡、推行新政、抗击外敌，逐步掌控朝堂话语权）→ 鼎定乾坤（外平蛮夷、内除积弊，架空皇权或受禅登基，开启大航海或工业萌芽）。\",\"worldSetting\":\"多设定于秦汉、三国、盛唐、两宋、晚明等剧烈变动或具有强烈意难平的历史节点；世界遵循真实的冷兵器作战法则、封建宗法等级、小农经济规律及滞后的信息交通传播限制，氛围兼具金戈铁马的悲壮与朱门弄权的阴沉。\",\"typicalCharacters\":\"主角多为理科技术流工程师、现代官僚/社畜精明人或军警；配角包含多疑威严的当朝帝王、老谋深算兼顾家国的内阁宰辅、耿直死谏的清流御史、以及待价而沽的名将谋士，反派往往是代表落后生产力与腐朽私利的门阀首脑。\",\"pacingAdvice\":\"前期注重微观爽点（搞钱、发明、文抄、装逼打脸乡绅），节奏要轻快；中期转向宏观叙事（朝堂论辩、边疆战事、战役推演），加重伏笔与权谋暗线；每20万字左右完成一次官职或地盘的跃升，战役与政治斗争交替进行，避免连续长篇战争或纯枯燥的政务描写导致疲劳。\",\"representativeWorks\":\"《新宋》、 《官居一品》、 《宰执天下》、 《晚明》、 《覆汉》\",\"commonPitfalls\":\"古人降智化（把千古帝王宰辅写成无脑工具人，现代人随便甩两句现代词汇对方就纳头便拜）；科技树暴走（无视基础工业条件直接徒手搓枪炮炸药导致战力崩盘）；现代道德强行绑架古人（脱离生产力空谈人人平等，盲目废除奴隶制或搞民主选举引发违和）；考据狂魔化（大段直接复制粘贴史料维基百科，冲淡剧情推进与角色塑造）。\"}" },
  { id: "genre_history_alt", profileJson: "{\"positioning\":\"依托古代政治制度、社会阶层与地缘军事逻辑，摆脱真实历史人物与生卒年束缚的宏大王朝争霸或权谋推演小说。\",\"sellingPoint\":\"既有扎实厚重的历史质感与权力博弈，又无真实历史考据的束缚；读者享受从微末起步到权倾朝野（乃至黄袍加身）、现代技术与制度降维改造落后王朝、横扫列国内乱的推演快感与爽感。\",\"coreConflict\":\"主角先进的认知/生产力与落后封建体制、世家门阀利益集团的死斗；主角生存壮大诉求与皇权猜忌、朝廷党争、外敌入侵之间的白热化博弈。\",\"readerExpectation\":\"世界逻辑自洽严谨，严禁弱化古人智商；权谋博弈与兵戈交锋要有真刀真枪的智力感和代价感；主角的科技攀爬、军政改革要符合物质基础，最终兑现重塑山河、开创盛世的成就感。\",\"classicStructure\":\"三阶段进阶流：前期微观破局，主角借穿越优势赚钱自保、解决乡绅/县衙危机并完成原始积累；中期踏入中枢或军旅，卷入夺嫡党争、经略封地根据地，以功勋换取政治实权；后期天下大乱或皇权崩塌，主角起兵清君侧或逐鹿中原，推翻旧制建立新秩序。\",\"worldSetting\":\"多为借用类唐、宋、明体制的平替王朝或乱世诸侯割据版图；拥有严密的宗族、科举、门阀、赋税及官僚体系，外围伴随草原游牧民族或异族蛮夷的边疆威胁，强调粮食、盐铁、兵源等客观物质制约。\",\"typicalCharacters\":\"主角（清醒理智的现代技术官僚/军政务实派）、博弈者（深沉多疑的帝王/精于算计的权相世家）、宿敌（野心勃勃的枭雄皇子/能征善战的草原可汗）、辅佐者（忠勇的寒门悍将/精于治生算计的管账谋士）。\",\"pacingAdvice\":\"前期小步快跑，每3-5万字达成一次微观发明或除恶立威爽点；中期拉长战线，每10-15万字完成一次重大党争反杀、军功晋升或领地扩建；后期重在宏观地缘推演，每30-50万字完成灭一国或平定一方叛乱，情绪层层加压后集中爆发。\",\"representativeWorks\":\"《庆余年》、顿号《赘婿》、顿号《枭臣》、顿号《随波逐流之一代军师》、顿号《大魏宫闱》\",\"commonPitfalls\":\"架空变悬浮：逻辑脱离封建社会生产力规律（如几天内量产火枪火炮、古代平民无条件接受现代民主平权）；降智权谋：将皇帝、重臣写得如同市井无赖任主角玩弄；主线漂移：前期经商暴富后缺乏政治野心与转化路径，导致故事沦为琐碎古代日常流水账。\"}" },
  { id: "genre_history_power", profileJson: "{\"positioning\":\"以古代王朝权力中枢为核心舞台，聚焦皇权制衡、党争倾轧与官场博弈的高智商政治推演小说，基调偏深沉、冷峻与机变。\",\"sellingPoint\":\"智商在线的杀局与破局、草蛇灰线的连环计谋、借力打力借势杀人的政治爽感，以及看主角在多方势力绞杀中步步登顶、执掌天下生杀大权的掌控感。\",\"coreConflict\":\"皇权集中与相权/门阀/藩王的分权矛盾，主角的政治野心/改良抱负与既得利益集团、吃人官场潜规则之间的不可调和。\",\"readerExpectation\":\"对手绝不无脑降智，局中人各怀鬼胎、动机符合政治立场与人性自私；主角破局依靠制度规则、信息差和人性弱点，而非纯靠武力掀桌或现代科技降维打击。\",\"classicStructure\":\"开局：卷入党争必死局或皇子夺嫡边缘，以小案为切口破局立足；中盘：进入中枢（六部/内阁/厂卫），通过赈灾、科举、军饷等大案连根拔除对手羽翼，组建核心政治班底；后期：直面至高皇权或权臣垄断，通过政变、逼宫或法理接盘实现问鼎。\",\"worldSetting\":\"多设在高度成熟的封建王朝中晚期（或参考明清、宋唐），核心场景为金銮殿朝会、内阁直房、部院公堂、诏狱密室与私密茶楼；运行规则严格受制于封建礼法、宗族特权、官制品阶与帝王制衡之术。\",\"typicalCharacters\":\"主角多为隐忍狠绝、善辨人心的权谋孤勇者；核心配角包含猜忌刻薄的老皇帝、深不可测的内阁首辅、凶狠阴毒的特务头目、迂腐但有风骨的御史清流、利字当头的世家家主。\",\"pacingAdvice\":\"前期小局速破（5-10章完成一次借刀杀人或脱罪自保）奠定智商口碑；中期转入大案布局（30-50章一卷），明暗双线交织，多处暗子铺垫，在金銮殿对质或大朝会时集中引爆，形成大宣泄爽点；不可连续长期高压烧脑，需穿插日常拉拢、利益分赃与官场人情转换节奏。\",\"representativeWorks\":\"《官居一品》、 《庆余年》、 《宰执天下》、 《琅琊榜》、 《大明王朝1566》\",\"commonPitfalls\":\"反派弱智化和脸谱化（把政治斗争写成流氓约架）；主角脱离封建历史规律，用泛道德化或现代幼稚人权思想说教；滥用武力超人掀桌破坏政治规则；大案虎头蛇尾，布局宏大却靠对手低级失误收场。\"}" },
  { id: "genre_history_war", profileJson: "{\"positioning\":\"以历史乱世或架空大乱局为背景，主角通过军事征伐、内政种田与地缘博弈，由微末势力逐步扫平割据群雄、驱逐外敌并最终定鼎天下的宏大战争叙事。\",\"sellingPoint\":\"版图从一县一隅扩张至万里江山的势力养成爽感；大军团阵地战与奇谋迭出的战略推演；各路文臣名将归心入麾的“集邮式”满足；推翻旧秩序、建国立业黄袍加身的终极权谋成就感。\",\"coreConflict\":\"新兴割据政权与垂死老牌帝国或外部强敌的生存绞杀；多方诸侯势力之间的地缘吞并与合纵连横；主角集团内部推行集权改革与既得利益集团（世家门阀、勋贵藩镇）的阶级矛盾。\",\"readerExpectation\":\"符合军事常识与后勤逻辑的硬核战役；主角杀伐果断、具备帝王气度的决策手腕；君臣相得、群英荟萃的丰满群像；大国重器的工业/经济降维打击；决不妥协的扫平天下与登基名场面。\",\"classicStructure\":\"微末起势（破局立足，占小城、造私兵、打赢首战立威）→ 割据一方（借乱世之势吞并周边，夺下一州之地，建立幕府官僚与军工后勤体系）→ 问鼎中原（官渡/赤壁式主力决战，破强敌、灭异族，平定半壁江山称王）→ 定鼎天下（兵临旧都，完成大一统，改朝换代重塑天下秩序）。\",\"worldSetting\":\"多设于王朝末世或架空割据时代。朝廷腐朽、土地兼并严重、天灾人祸导致流民遍地，诸侯四起。主要场景交替于泥泞血腥的攻防前线、关隘险地、排兵布阵的沙盘幕府以及暗流涌动的宫廷朝堂。\",\"typicalCharacters\":\"主角是兼具现代眼光与冷酷政治手腕的领袖枭雄；配角包含“王佐之才”的内政总管、“奇谋百出”的顶级谋士、“独当一面”的兵团统帅与“万人敌”陷阵先锋；对手为盘根错节的千年世家门阀家主、老辣残忍的边镇军阀或凶暴善骑射的异族雄主。\",\"pacingAdvice\":\"遵循“战役推进—战后消化”的循环节拍。每场核心大战（谋划-交锋-逆转）后必须穿插内政消化期（整编降卒、分配田亩、研发军械、封赏文武），战役规模由千人械斗逐级升级至十万级决战；切忌连环大战导致疲劳，也不可过度陷入种田细节导致剧情停滞。\",\"representativeWorks\":\"《枭臣》、 《江山美色》、 《大争之世》、 《覆汉》、 《篡清》\",\"commonPitfalls\":\"战争儿戏化（主角靠个人武勇决定数万人战役胜负，忽视后勤粮草与地形天候）；政治降智化（反派世家与朝臣行为无脑低幼，缺乏符合利益立场的博弈）；主角圣母化（在争霸节点心慈手软、滥施仁慈导致部下寒心）；后期崩盘（势力膨胀后缺乏多线驾驭能力，沦为同质化的无脑平推地图）。\"}" },
  { id: "genre_scifi_root", profileJson: "{\"positioning\":\"以科学假说、前沿技术或未来文明推演为核心推力，融合宏大宇宙奇观与技术降维打击的硬核脑洞题材。\",\"sellingPoint\":\"科技降维打击带来的支配爽感、颠覆常识的硬核脑洞、宏大文明造物（戴森球、环形世界）的巨物崇拜，以及人类在冷酷宇宙法则下向死而生的文明史诗感。\",\"coreConflict\":\"个体与高度异化的科技体制/AI霸权之争，脆弱的人类文明与不可名状的宇宙高维文明/黑暗森林法则之间的生存争夺，以及技术爆发带来的伦理失控与阶层固化。\",\"readerExpectation\":\"底层逻辑自洽的科学推演、具有视觉冲击力的未来奇观、通过智慧与科技完成绝境破局的智商优越感，绝不接受毫无物理常识的胡编乱造与换皮玄幻。\",\"classicStructure\":\"开篇常以‘微观绝境/技术奇点降临’切入，主角获得关键科学理论或地外造物；中期展开‘工业攀爬与技术变现’，形成技术垄断与势力崛起；后期走向‘星海拓荒与文明碰撞’，最终直面高维威胁完成文明升维或拯救。\",\"worldSetting\":\"多设定于赛博朋克近未来、深空漂泊的孤舟母舰、死寂严酷的异星拓荒地、或者遵循黑暗法则的冷酷星际，强调精密机械感、冷色调数据流与苍凉宏大的宇宙空间。\",\"typicalCharacters\":\"主角多为理智克制、重度技术宅或兼具战略眼光的科研领袖；核心标配一个兼具人性反差的高级AI助手；配角常设狂热的义体机械狂人、冷酷的星舰政客以及作为对照组的高维文明傲慢观察者。\",\"pacingAdvice\":\"前期需紧扣‘技术研发-样品实验-震惊世界’的高频正向反馈闭环，每10-15章完成一次科技代差验证；中期拉长战线进行星际建设与军备竞赛；大决战切忌冗长缠斗，多以战术思维与科技底牌瞬间逆转战局。\",\"representativeWorks\":\"《三体》、 《深空之下》、 《学霸的黑科技系统》、 《修真四万年》、 《死在火星上》\",\"commonPitfalls\":\"大段堆砌维基百科式的技术说明导致阅读枯燥（说明文陷阱）；用星际皮囊写低智近身格斗或宫斗（皮相科幻骨子里玄幻）；文明代差表现无力，外星高等文明智商降维如野蛮人；过度陷入无解的文青式绝望而丧失爽感。\"}" },
  { id: "genre_scifi_near_future", profileJson: "{\"positioning\":\"以30至100年后的现实延伸为骨架，聚焦强人工智能、脑机接口、合成生物学或聚变能源对人类社会、伦理秩序与日常阶层产生颠覆性重构的写实向推演科幻。\",\"sellingPoint\":\"“比现实多走半步”的极强代入感与细思极恐的推演沉浸；前沿科技被资本或寡头垄断后的社会阶层撕裂；主角利用信息差、硬核科技逻辑或底层漏洞对既有庞大系统实施降维打击的智斗爽感。\",\"coreConflict\":\"急速狂飙的生产力与停滞甚至倒退的分配伦理之间的撕裂，表现为巨型科技寡头对算力/基因资源的垄断与普通人数字人权的剥夺，以及人类在义体异化、AI觉醒边缘的技术自毁危机。\",\"readerExpectation\":\"严密自洽且具备现实映射的硬核推演（绝非披皮玄幻）；科技不仅是战力数值，更是深入衣食住行与犯罪黑产的生活肌理；对抗依靠技术漏洞挖掘与缜密逻辑，而非唯心爆发。\",\"classicStructure\":\"微观切入：主角因底层边缘案件（如非法义体改装、脑机记忆走私、新型算法审查）被卷入风暴；中局抽丝剥茧：顺着黑产技术链条层层向上破译巨型财阀或政府AI的技术黑箱；终局剧变：引爆算力/能源奇点，在旧秩序坍塌中重构人机契约或社会结构。\",\"worldSetting\":\"高科技与低生活并存的半废土/巨构城市；街道充斥AR全息广告与无人配送无人机，而底层贫民靠沉浸舱与合成蛋白块度日；算力即货币，代码即法律，跨国托拉斯控制公共市政，存在法律真空的赛博黑市与技术法外区。\",\"typicalCharacters\":\"主角多为底层黑客、前财阀核心技术员、义体清道夫或数字侦探，性格冷静克制、务实且熟稔系统漏洞；配角通常配备意识觉醒的人工智能、冷酷理性的企业安全总监、提供地下技术支援的黑市义医，以及反科技原教旨抵抗军领袖。\",\"pacingAdvice\":\"前期必须在3万字内通过一场贴合日常的科技冲突（如信用分熔断、记忆篡改危机）确立生存危机；每10万字完成一次科技代差的攻破或底层权力的颠覆；技术设定需融入追逐、潜入、黑客攻防等高压行动中，杜绝大段论述性说明文。\",\"representativeWorks\":\"《赛博英雄传》、顿号《我们生活在南京》、顿号《死在火星上》、顿号《学霸的黑科技系统》\",\"commonPitfalls\":\"盲目照搬欧美日系赛博朋克的贫民窟酒馆套路，丧失本土烟火气与现实质感；后期战力失控滑向“科技修仙”，把量子力学和纳米技术当成内力和法术来写；空有宏大技术构想，人物动机沦为工具人，缺乏在科技压迫下作为“人”的情感羁绊与现实痛感。\"}" },
  { id: "genre_scifi_cyberpunk", profileJson: "{\"positioning\":\"立足于‘高科技、低生活’反乌托邦社会，底层边缘人借助义体改造与黑客技术向托拉斯寡头抗争的冷酷反叛史诗。\",\"sellingPoint\":\"军工义体与赛博黑客带来的感官爆破战斗；底层蝼蚁以命相搏、撕碎财阀伪善秩序的反叛快感；机械飞升与人性留存的宿命纠葛；声色犬马霓虹都市与肮脏赛博街头的极致视听反差。\",\"coreConflict\":\"无权无势的底层个体与垄断肉体、意识乃至生死权限的跨国巨型企业之间不可调和的阶级碾压与生存反抗；机械改造对血肉人性的逐步蚕食（赛博精神病/异化）与为了生存必须不断换装更强义体的生存悖论。\",\"readerExpectation\":\"硬核炫酷的未来科技插件展示；不跪舔资本、快意恩仇的狂徒朋克精神；高烈度的枪火与神经黑客攻防；主角在绝望冰冷的钢铁森林中守住属于人类的最后一点温情与尊严。\",\"classicStructure\":\"底层开局（拾荒者/落魄佣兵/被开除的公司狗陷入生存绝境）→ 意外截获顶级军工芯片或失落AI打破死局 → 依托黑诊所与地下中间人接单做委托、迭代义体装备、打响街头名号 → 卷入财阀高层权斗或绝密人体实验黑幕 → 小队遭背叛/核心配角牺牲引发情绪决堤 → 主角杀穿安保部队、向摩天大楼顶端的资本神明亮剑并完成自我证明。\",\"worldSetting\":\"永无止境的酸雨与遮天蔽日的霓虹全息巨屏；阶级极端分化的垂直立体城市（浮空城/顶层豪阀与地面贫民窟/辐射废土）；神经虚拟网络、完全私有化的执法武装；生命、记忆与意识皆可明码标价的极端资本主义世界。\",\"typicalCharacters\":\"主角：冷酷利落、身手敏捷、底线清晰且不甘做奴隶的独狼佣兵或顶级黑客；配角模板：消息灵通且游走于黑白两道的酒保中间人、嘴碎心软的黑诊所义体医生、神经刀式崇尚火力的重装肉盾、沦为企业抹杀工具的改造人死士（反派宿敌）。\",\"pacingAdvice\":\"前3章内必须爆发带有明显赛博特质的血腥遭遇战或网络入侵，快速确立金手指；以‘接取灰色委托-遭遇意外危机-绝境极限反杀-获得关键义体配件/企业绝密数据’为一个小周期（8-12章）；紧绷的高强度战斗后要有短暂的黑市修整与市井温情作为缓冲，时刻悬挂‘赛博精神病阈值’或‘身体排异反应’作为倒计时紧迫感。\",\"representativeWorks\":\"《神经漫游者》、 《赛博英雄传》、 《赛博时代的魔女》、 《夜的命名术》、 《我在赛博开武馆》\",\"commonPitfalls\":\"有‘赛博’无‘朋克’，主角毫无反抗精神甚至轻易被大企业收编沦为体制工兵；披着赛博皮写都市异能或传统修真换皮，丢失了阶级压迫与技术伦理深度；生造过多晦涩难懂的科幻硬名词导致说明文过载；义体改造无副作用与代价，丧失了在血肉与机械边缘挣扎的悲壮感。\"}" },
  { id: "genre_scifi_apocalypse", profileJson: "{\"positioning\":\"以极端灾变、科技失控或宇宙级异变为背景，聚焦技术突围、基地建设与文明秩序重构的硬核生存小说。\",\"sellingPoint\":\"降维天灾压迫下的极限求生快感；黑科技/移动基地/机甲一步步升级带来的绝对安全感与碾压爽感；从朝不保夕的废土拾荒到重铸人类文明秩序的宏大史诗感。\",\"coreConflict\":\"毁灭性极端环境及科技畸变体对人类生存空间的绝对挤压；有限的生存资源、工业火种与人性崩溃下的废土割据势力之间的零和博弈。\",\"readerExpectation\":\"灾难爆发前后的紧迫备战与囤积快感；主角杀伐果断、理智实用但不丧失底线的人格魅力；自洽的硬核科幻设定推演；科技树点亮与安全区扩张带来的具象化成就感。\",\"classicStructure\":\"开局（灾变降临/前夕囤资、抢夺核心科技或庇护所萌芽）→ 前期（微观求生、点亮基础科技树、肃清周边威胁建立绝对安全区）→ 中期（基地模块化升级、吸纳技术人口、抵御天灾浪潮与大型掠夺军阀）→ 后期（解开灾难起源真相、对抗智械/外星/高维灭世源头、带领人类重燃文明火种）。\",\"worldSetting\":\"极寒冰封、辐射尘埃、智械废墟或变异生态覆盖的崩坏地表；以严苛的热力学定律、能源枯竭、环境毒性为物理铁律；舞台多为地下多层掩体、改装重型移动要塞、浮空城及钢铁遗迹废土。\",\"typicalCharacters\":\"主角多为理智果决的工程师、前特种军人或手握文明黑科技火种的实用主义者；配角涵盖痴迷技术修复的机械师、冷血割据的军阀枭雄、恪守旧时代道德的悲剧守护者以及忠诚精干的作战班组。\",\"pacingAdvice\":\"维持“生存危机迫近→技术突破/装备升级→极限反杀并暴富收割”的高频小循环；前30章密集展现生存资源与安全防御建设，中期每10-15章推进一次工业化或势力范围跃进，大高潮配合周期性天灾（如辐射风暴、机械狂潮）引爆战力成果。\",\"representativeWorks\":\"《重卡战车在末世》、 《我的末世基地车》、 《第一序列》、 《全球冰封：我打造了末日安全屋》、 《深渊独行》\",\"commonPitfalls\":\"主角盲目圣母扶贫导致安全屋暴露、违背生存逻辑；中后期战力崩坏，纯科幻推演直接滑向唯心修仙而失去末日硬度；忽视后勤与工业链逻辑，凭空手搓高精尖武器；过早陷入低维度的营地勾心斗角，稀释了末世天灾科幻的宏大感与生存压迫。\"}" },
  { id: "genre_scifi_space", profileJson: "{\"positioning\":\"以深空远航、未知星域探索与失落文明发掘为主轴，融合舰船养成、多元种族博弈与宏大太空战役的浪漫派或硬核太空歌剧。\",\"sellingPoint\":\"揭开宇宙神秘面纱的未知探索感；从破旧护卫舰一路升级至歼星级母舰或私人舰队的养成爽感；跨星系尺度的战术跃迁、轨道轰炸与黑科技碾压。\",\"coreConflict\":\"渺小拓荒个体/边缘势力与残酷星际生存法则（黑暗森林、高维掠夺者）的生存对抗，以及跨星系巨头垄断、星际帝国争霸对未知资源的疯狂掠夺。\",\"readerExpectation\":\"瑰丽且具备合理科幻想象的宇宙奇观；科技树解锁与舰船装备实打实的战力提升；不降智的太空战术与星海博弈；纯粹的星辰大海征服欲而非缩在单颗星球勾心斗角。\",\"classicStructure\":\"开局起步（边缘星球/垃圾星接取高危勘探任务，获得核心黑科技或远古火种）→ 拓荒积累（组建专业团队，改装破舰，在星际黑市与险地夹缝求生）→ 势力崛起（打通未知航线，获得资源星或星区驻地，打响舰队战）→ 终极揭秘（对抗宇宙级天灾文明或高维遗迹，影响整个银河的命运走向）。\",\"worldSetting\":\"以超光速跃迁、星门网络维系的庞大星河网，分布着高度官僚化的星际帝国、跨星系联合财阀、法外星盗星区，以及充斥致命辐射与外星遗骸的荒芜迷航带。\",\"typicalCharacters\":\"冷静果决且精通星图测绘/舰船指挥的主角舰长；吐槽役且算力惊人的毒舌舰载AI；技术疯子型机械改造师；身负灭族之仇或拥有特殊感应能力的异星向导/战斗员。\",\"pacingAdvice\":\"以“星际探险-危机交火-战术反杀-黑科技/资源收割-战舰升级”为中闭环（30-50章一处星系遗迹）；地面探索与太空海战比例建议三七开；战舰性能提升必须立刻通过遭遇战完成火力验证与视觉爽感兑现。\",\"representativeWorks\":\"《小兵传奇》、陈词懒调《星级猎人》、最终永恒《深空之下》、骷髅精灵《星战风暴》、卧牛真人《修真四万年》\",\"commonPitfalls\":\"星际换皮（打着星际旗号大半篇幅在写地面单兵肉搏或异能都市，完全丢失星舰与宇宙尺度）；尺度崩塌（对光年、光速、天体质量缺乏基本概念，跃迁如逛菜市场）；设定狂魔（开篇堆砌几千字硬核科技设定与论文，导致剧情节奏极其拖沓）；视野狭隘（主角拥有星际力量却沉迷于某个原始文明的宫斗泥潭）。\"}" },
  { id: "genre_suspense_root", profileJson: "{\"positioning\":\"以现实阴暗面或超自然异常为切入点，通过致命危机压迫、高智商推理解谜与未知恐惧驱动的情绪向强情节题材。\",\"sellingPoint\":\"身临其境的窒息压迫感与险象环生的逃生刺激；在必死杀局与诡异规则中抽丝剥茧、极限破局的智力快感；层层反转直至揭开世界真相的巨大心理释放。\",\"coreConflict\":\"凡人认知/生存本能与不可名状的恐怖力量或扭曲规则的对抗；生死绝境下极端人性之间的信任与背叛。\",\"readerExpectation\":\"硬核严谨的逻辑闭环、全程在线的智商博弈、细思极恐的氛围营造，以及拒绝机械降神的高水准反转与真相揭晓。\",\"classicStructure\":\"开篇以突发悬案或致命异常打破日常，快速立下‘不破局即死亡’的高压动机；中期以‘封闭空间/规则副本’单元剧形式推进，主角在试探规则、遭遇追杀、寻找生路中收集线索；后期将零散谜题串联至幕后黑手或世界底层真相，完成终极对抗与升华。\",\"worldSetting\":\"多为现代都市背景下的里世界、规则怪谈领域或封闭封闭死地（如老旧公寓、废弃医院、深夜末班车等），具有不可硬抗的致死规则、潮湿阴冷的心理暗示以及高度危险的信息差。\",\"typicalCharacters\":\"主角多为冷静理智、洞察力极强的高智商求生者或性格偏执的疯批狂人；配角包括用于试探规则触雷的炮灰角色、掌握碎片信息的神秘领路人，以及不可信赖的临时盟友；反派则为不可名状的诡异源头、扭曲的人性恶徒或跨越维度的庞大邪恶组织。\",\"pacingAdvice\":\"遵循‘压迫积攒-悬念拉满-窒息爆发-绝地破局-情绪释放’的抛物线节奏。单事件控制在15-25章内，避免悬念拖得太长导致读者疲劳；副本之间必须安排喘息期与线索结算，防止神经紧绷导致读者弃读。\",\"representativeWorks\":\"《我有一座冒险屋》、 《神秘复苏》、 《地狱公寓》、 《民调局异闻录》、 《诡秘地海》\",\"commonPitfalls\":\"前置谜团过于宏大导致后期烂尾崩盘；为制造危机强行让主角或配角降智作死；解谜全靠机械降神或外挂平推，丧失智斗悬疑内核；通篇沉溺于恶心血腥描写而缺乏精妙的心理惊悚。\"}" },
  { id: "genre_suspense_detective", profileJson: "{\"positioning\":\"以一线警务侦查、物证刑技与逻辑闭环为核心驱动，聚焦罪案真相还原与人性博弈的现实向悬疑破案小说。\",\"sellingPoint\":\"抽丝剥茧还原真相的智力解谜快感、硬核刑侦技术与微表情审讯的专业代入、蛛丝马迹闭环时的反转震撼，以及正义必胜带来的法理道德爽感。\",\"coreConflict\":\"办案刑警与高智商罪犯的反侦查较量；程序正义与实体正义的现实拉扯；陈年旧案受害者宿命与体制内外阻力的终极清算。\",\"readerExpectation\":\"严密无漏洞的证据链推演（拒绝机械降神与主角开天眼）；扎实专业的一线刑侦细节（法医、痕检、网安）；反派作案动机具备心理深度与社会痛点；所有伏笔皆有合理解释。\",\"classicStructure\":\"经典“单元案+主线案”糖葫芦串联结构。开篇高冲击命案现场切入，迅速确立死因并锁定多重嫌疑人；中期通过交叉审讯、假线索排除与第二受害者制造危机；案末通过关键物证绝杀破局，并引出贯穿全书的核心宿命大案碎片。\",\"worldSetting\":\"多设于地级市公安局刑侦支队、法医解剖室、逼仄审讯室与充满烟火气的底层城中村；遵循真实法治流程与物证保管规则；整体基调冷峻压抑，兼具世俗人情味与时代浮世绘感。\",\"typicalCharacters\":\"主角多为直觉敏锐且背负旧日心魔的硬汉刑警，或具备顶级观察力的非典型技术专家/顾问；标配理性冷静的专业法医/痕检搭档、插科打诨的忠诚老刑警副手；反派多为逻辑严密、拥有悲剧色彩或极端执念的高智商罪犯。\",\"pacingAdvice\":\"3至5章抛出一个关键疑点或突发线索反转，保持推理推演的信息密度；10至15章完成一次局部嫌疑人排查或小冲突高潮；30至40章彻底侦破一个完整单元案件并收拢证据链，同时递进主线核心阴谋，切忌长时间无办案进展的纯日常灌水。\",\"representativeWorks\":\"《心理罪》、 《法医秦明》、 《余罪》、 《默读》、 《猎凶者》\",\"commonPitfalls\":\"刑侦常识硬伤（如越权跨区办案、破坏现场物证、审讯刑讯逼供）；主角凭借毫无证据的“直觉心证”直接定罪；凶手在最后自我招供缺乏物证支撑；案件铺垫过大但收尾归咎于凶手精神失常；为了悬疑刻意隐瞒读者已知视角进行虚假欺骗。\"}" },
  { id: "genre_suspense_thriller", profileJson: "{\"positioning\":\"以不可知、不可抗的致命危险为驱动，融合心理压迫、密闭恐惧与迷局破解，主打“极限求生+真相解构”的沉浸式高压题材。\",\"sellingPoint\":\"背脊发凉的细思极恐细节、濒临死亡倒计时的压迫感、在死亡规则中寻找微小生路的智力快感，以及撕开伪装窥见骇人真相时的情绪颠覆。\",\"coreConflict\":\"渺小人类在具备绝对压迫力的异常存在（怨异、规则异变、未知畸变）面前的生存博弈，以及主角探寻真相与幕后规则同化/灭绝之间的阻抗冲突。\",\"readerExpectation\":\"安全距离下的高浓度刺激体验；严谨自洽且可被破解的恐怖规则；主角面对绝境时冷静克制的智斗破局；收尾时合乎逻辑的解答，拒绝降智唯心与机械降神。\",\"classicStructure\":\"“单元怪谈+暗线拼图”推进模式。开局抛出诡异异常或死亡倒计时，以第一起惨烈死伤立下恐怖规则；中局通过收集线索、试错禁忌、险象环生地完成阶段性求生；终局串联各单元伏笔，直面源头源质或引爆世界观级惊天反转。\",\"worldSetting\":\"多设于“表层日常与底层崩坏”交织的现代都市、废弃封闭空间（如凶宅、疯人院、停运地铁）或民俗封闭闭环；空间内充斥着不可违逆、带有逻辑陷阱的致命法则与因果律机制。\",\"typicalCharacters\":\"主角多为高智商、情绪钝化或心理承受力极强的“冷静求生者”；配角包含违反禁忌导致危机的莽撞者、心怀鬼胎隐瞒线索的自私者、提供线索的受害者，以及难以捉摸的非人异端。\",\"pacingAdvice\":\"遵循“紧-极紧-破局-微松-新伏笔”的波浪式循环。前3章必须引爆致命危机，探索期每2-3章设置一次危险逼近或规避测试；单次解密后仅留半章至一章整理线索，严禁长篇生活日常冲淡好不容易建立的惊悚阈值。\",\"representativeWorks\":\"《我有一座冒险屋》、 《神秘复苏》、 《地狱公寓》、 《青叶灵异事务所》、 《恶魔公寓》\",\"commonPitfalls\":\"依赖血腥恶心描写代替心理惊悚；主角金手指过强过早打穿战力体系导致恐惧感彻底崩盘变成无脑爽文；解密过程缺乏逻辑硬套主角光环；结局强行解释为“精神分裂、幻觉吃药或做梦”引发读者众怒。\"}" },
  { id: "genre_suspense_weird_rules", profileJson: "{\"positioning\":\"以逻辑陷阱与认知污染为核心，通过‘绝对规则’构建生存困境的智斗解谜类悬疑惊悚小说。\",\"sellingPoint\":\"在充满恶意与悖论的规则文本中寻找逻辑破绽的智力快感；细思极恐的心理惊悚与规则反常带来的诡异氛围；利用规则甚至反向操控规则‘卡Bug’反杀怪谈的极致爽感。\",\"coreConflict\":\"人类有限认知与不可名状诡异存在之间的博弈；真伪规则与精神污染之间的对抗；遵守规则沦为养料与打破规则即死之间的生存悖论。\",\"readerExpectation\":\"严密自洽的推理解密过程，读者能够与主角同频进行线索推理；主角极度冷静、绝不圣母且智商在线；对日常场景（家庭、学校、动物园、医院等）进行令人毛骨悚然的重构与颠覆。\",\"classicStructure\":\"单元副本推进制：开局直给‘守则/纸条’构建诡异压迫感；前期通过炮灰违规展现恐怖死亡代价；中期出现规则互斥或真假污染，主角逼入绝境；后期发现隐藏规则或文字游戏漏洞，反制规则源头通关结算。\",\"worldSetting\":\"高度封闭且日常化的微观现实场景，表面维持正常秩序但深层规则扭曲；环境充斥‘它’的阴影、认知滤镜、红黑字纸条、断章日记与不可直视的禁忌，强调理智值（San值）的滑落与环境异化。\",\"typicalCharacters\":\"主角多为极度理性的心理学/逻辑学达人、具备‘错误免疫/真实之眼’等微挂的幸存者，或逻辑清奇的精神病型反常规反英雄；配角涵盖冲动破戒的送命炮灰、盲信权威的跟风者、各怀鬼胎的资深挑战者，以及半人半诡的场景NPC。\",\"pacingAdvice\":\"以‘见规则-踩小雷-死配角-大冲突-破核心’为微循环；单副本篇幅宜精简（通常15-30章），每2章内必须推进一条逻辑推理或爆发生死危机；通关后设置短暂现实/休息区做爽点沉淀，切忌战力过快膨胀削弱惊悚感。\",\"representativeWorks\":\"《动物园规则怪谈》、 《规则怪谈：我的家人不正常》、 《规则怪谈：我能完美利用规则》、 《神秘复苏》\",\"commonPitfalls\":\"规则漏洞百出且作者圆不上，导致逻辑彻底崩盘；过度依赖系统武力平推而放弃‘规则智斗’核心；后期世界观无限拔高变成修仙或战力对轰玄幻文；解谜过程全靠主角拍脑袋或机械降神，剥夺读者推理解谜乐趣。\"}" },
  { id: "genre_suspense_infinite", profileJson: "{\"positioning\":\"以高维诡异系统或神秘APP为枢纽，主角在封锁、惊悚的独立规则空间中，依靠解谜、心理博弈与规则漏洞寻求生存与破局的悬疑求生小说。\",\"sellingPoint\":\"惊悚悬疑氛围带来的持续压迫感；规则怪谈与民俗恐怖杂糅的新鲜感；高智商主角在绝境中洞察机制、卡系统Bug极限翻盘的智力碾压爽感。\",\"coreConflict\":\"渺小求生者与全知残虐规则机制之间的存亡博弈；极端绝境下玩家为了微薄生机而爆发的人性猜忌与背叛；底层求生者与幕后造物主/系统运行逻辑的终极对抗。\",\"readerExpectation\":\"硬核严谨的逻辑闭环与烧脑反转；主角冷静理智、双商在线且绝不圣母；恐怖氛围与压迫感始终在线，绝不希望看到中期直接沦为纯武力横推玄幻战。\",\"classicStructure\":\"单元剧套路串联主线：新手副本试炼确立主角独特特质与行事风格 -> 现实/中转站喘息整顿并铺设系统身世悬念 -> 进阶副本引入团队合作与玩家阵营对抗 -> 核心主线副本直面系统真相并尝试推翻或掌控规则。单副本通常遵循‘宣布规则-出现死者-收集线索-陷入死局-逻辑反转破局’的递进闭环。\",\"worldSetting\":\"多维封闭式诡异空间。枢纽通常为黑棺、诡异列车、恐怖APP或高维意识空间；微型副本场景涵盖中式民俗古村、封闭疯人院、规则怪谈校园、无限回廊与深海孤岛；底层法则是‘规则即天道，触碰必死，但生路必隐于死路之中’。\",\"typicalCharacters\":\"主角多为‘高智商观察者’、‘情感缺失者’或‘算计极致的微疯狠人’；配角包含‘自作聪明的炮灰老手’、‘背刺型利己主义者’、‘能力互补的铁血打手/道具大师’；副本Boss多为遵循悲惨因果与规则机制的厉鬼执念或系统执行者。\",\"pacingAdvice\":\"单副本篇幅宜控制在5至12万字，避免审美疲劳。开局3章内必须触发核心规则并产生致命危机；副本内每1.5至2万字安排一次规则试错与逻辑推进；副本通关后保留1至3章的奖励结算与现实/主城信息交互，形成‘紧绷-释放-再紧绷’的波浪式节奏。\",\"representativeWorks\":\"《地狱公寓》、 《死亡万花筒》、 《画怖》、 《地球上线》、 《末日乐园》\",\"commonPitfalls\":\"中后期战力与道具通胀，解谜惊悚沦为玄幻对轰；为了体现主角智商而刻意让全员配角降智送死；规则设定前后矛盾，无法自圆其说只能靠机械降神强行过关；副本同质化严重（连续出现鬼校、荒废医院等审美疲劳场景）。\"}" },
  { id: "genre_romance_root", profileJson: "{\"positioning\":\"以男女主角亲密关系的建立、推进与心理拉扯为核心主线，注重高共情体验、情绪价值兑现与情感陪伴感的通用母题材。\",\"sellingPoint\":\"极致的情感推拉（暧昧期的张力与荷尔蒙）、被唯一偏爱的极致安全感、身份/性格反差带来的互动萌点，以及冲破现实或世俗阻碍后的情绪大爆发。\",\"coreConflict\":\"亲密关系的靠近渴望与现实阻碍（如阶层差异、家族恩怨、过往心理创伤、生存目标冲突）之间的撕扯，以及从“彼此戒备/试探”到“彻底交心/非你不可”的心态转变。\",\"readerExpectation\":\"人设立体不崩塌，男主必须具备专一、偏爱等核心吸引力，女主必须拥有独立人格或讨喜特质；关键名场面（初见、吃醋、表白、并肩）情绪浓度拉满，结局必须情感圆满且逻辑自洽。\",\"classicStructure\":\"开篇：强设定或命运契机建立人物物理/利益捆绑；前期：日常碰撞、相互试探与微小的心动细节积累；中期：共同经历外部事件，打破心防，进入高甜或极限拉扯期；中后期：核心矛盾或重大危机爆发（掉马、误会、生死抉择），感情迎来终极质检；后期与结局：双向奔赴打破阻碍，确立永恒契约与甜蜜余韵。\",\"worldSetting\":\"跨越现言、古言、幻言等多元背景，核心在于构建能够制造“孤立独处环境”与“众目睽睽修罗场”的社会空间（如豪门宴会、合租同居、深宫权谋、职场职级），注重环境氛围对人物心境的投射与烘托。\",\"typicalCharacters\":\"男主多为禁欲权贵、偏执深情、高岭之花或痞帅忠犬，核心底层代码是“对全天下冷淡唯独对女主破例”；女主多为清醒自强、娇软坚韧或明艳飒爽，具有自身成长动机；配角多为助攻亲友团与推动关系的对照组/反派炮灰。\",\"pacingAdvice\":\"前三章必须完成男女主同框或建立强关联悬念；每5-8章需设置一次关系升温点（如眼神交汇、意外触碰、暗中吃醋）；暧昧期需拉长但拒绝原地踏步，每次互动都要推进心理距离；虐点后必须迅速跟进糖点补偿，杜绝长时间的无意义憋屈。\",\"representativeWorks\":\"《何以笙箫默》、顿号、《知否？知否？应是绿肥红瘦》、顿号、《难哄》、顿号、《黑莲花攻略手册》、顿号、《偷偷藏不住》\",\"commonPitfalls\":\"强行制造“长嘴不说”的低级误会拖延进度；男主霸道写成油腻冒犯、女主娇憨写成弱智依附；感情缺乏渐进逻辑，沦为工业糖精；配角降智恶毒太脸谱化；为了虐而虐导致主角人设彻底崩塌。\"}" },
  { id: "genre_romance_modern", profileJson: "{\"positioning\":\"以当代都市现实为舞台，聚焦男女主角在生活、职场与社会规则下的情感羁绊、拉扯试探与现实抉择，提供高度情绪代入与浪漫代偿的言情母题品类。\",\"sellingPoint\":\"高浓度的情感张力与暧昧推拉；现实阻力下的极致偏爱与双向救赎；男主强大的苏感与安全感；女主在亲密关系中的自我成长与被看见的心理满足。\",\"coreConflict\":\"亲密关系渴望与现实壁垒的博弈：包括阶层/家庭悬殊、职场利益冲突、过往心理创伤、异地与发展路径分歧，以及面对动心时的自我防备与信任重建。\",\"readerExpectation\":\"细腻且有说服力的心动轨迹；情绪价值充足（甜欲拉扯或克制深情）；男女主双商在线、感情专一；绝不接受恶俗降智误会、无底线雌竞与原则性出轨；结局必须情感圆满（HE）。\",\"classicStructure\":\"开篇建立高张力交集（重逢修罗场/契约同居/职场上下级/先婚后爱）；前期通过日常试探、信息差制造暧昧与身体/情绪破冰；中期外部现实危机或旧伤揭开促成坦白与关系质变；后期并肩解决现实阻碍实现情感闭环，以承诺与稳定未来收尾。\",\"worldSetting\":\"现代一二线都市空间（高档写字楼、老城区巷弄、合租公寓、特定行业职场等）；遵循真实社会的职业逻辑、家庭伦理与生活压力，但人际情感浓度经过浪漫化提纯，兼具都市摩登感与烟火生活细节。\",\"typicalCharacters\":\"男主：禁欲精英/清冷深情/桀骜不驯，外冷内热，对女主具有唯一性偏爱与极强性张力；女主：清醒独立、拥有明确职业追求或精神内核，并非依附型挂件；配角：提供情感助攻的知心闺蜜、提供戏剧阻力但动机合理的家庭长辈/竞争对手。\",\"pacingAdvice\":\"3-5章内必须有一轮高情绪浓度互动（对视、偶触、语言交锋、吃醋）；每15-20章推进一次亲密阶段跨越（破冰、告白、同居、拥抱/吻戏）；虐点或误会篇幅不宜超过3-5章，且需迅速以更强烈的心意确认对冲回甘；职业与日常生活线比例不宜超过40%，核心重心始终锚定在二人关系变化上。\",\"representativeWorks\":\"《何以笙箫默》、 《偷偷藏不住》、 《难哄》、 《你比星光美丽》、 《归路》\",\"commonPitfalls\":\"男女主缺乏情感交互基础就莫名深爱的“工业糖精”；女主完全丧失主体性变成男主衬托物；滥用“长嘴不解释”、堕胎车祸绝症等生硬狗血梗；职业背景悬浮且缺乏常识沦为“伪职场”；男主追求手段油腻越界、甚至带有现实冒犯感导致读者不适。\"}" },
  { id: "genre_romance_ancient", profileJson: "{\"positioning\":\"以古代宗法礼教与封建阶级为舞台，聚焦男女主在门第悬殊、内宅倾轧或朝堂权势约束下，实现生存破局与极致深情羁绊的古典情感叙事。\",\"sellingPoint\":\"封建礼教禁锢下克制且极具张力的情感拉扯；女主凭清醒心智在困境中逆风翻盘、借势立足的爽感；位高权重男主面对女主时独一份的偏爱、低头与宿命守护。\",\"coreConflict\":\"个人自主与宗法礼教（嫡庶、门第、孝道）的结构性压迫；内宅争产求生或朝堂夺嫡政见背离引发的利益博弈；主角彼此相爱与立场阵营、家仇国恨之间的两难抉择。\",\"readerExpectation\":\"女主内核稳定清醒，绝不做委屈隐忍的纯受气包与恋爱脑；男女主智商在线、势均力敌，互动有深层默契而非工业糖精；反派惩处合理痛快，古典风物与礼法规矩严密可信。\",\"classicStructure\":\"开篇抛置危机（重生/替嫁/落魄贬谪），迅速解决内宅首发险境立住清醒人设；中期双线并行，内肃宅院立规矩，外涉男主权谋利益结盟，借患难升级情感；后期卷入皇权变易或族灭风暴，联手破局打破身份禁锢，走向权势巅峰或归隐圆满。\",\"worldSetting\":\"多为架空仿唐宋明清的宗法制王朝，主要场景为高门侯府、深宫内院、江南世家或市井茶肆；充斥着森严的嫡庶尊卑、宗族家规与皇权高压，氛围兼具古典雅致与吃人礼法的压抑窒息感。\",\"typicalCharacters\":\"女主：深藏锋芒、隐忍算计的庶女/落难千金；男主：权倾朝野、冷情狠戾却为女主俯首的权臣/王爷/少年将军；配角群：佛口蛇心的当家主母、争宠嫉恨的姐妹、伪善薄情的渣爹、立场鲜明的政客与忠心机敏的贴身丫鬟。\",\"pacingAdvice\":\"内宅交锋讲究小步快跑，每3-5章完成一次借力打力的小反转反杀；男女主情感线需与外部危机绑定，从利益试探到交心托付层层递进；中期朝堂线切入拉大格局，避免全程局限于一院之争的审美疲劳。\",\"representativeWorks\":\"《知否知否应是绿肥红瘦》、顿号、《折腰》、顿号、《步步惊心》、顿号、《首辅养成手册》、顿号、《似锦》\",\"commonPitfalls\":\"现代白话与网络热梗泛滥，称谓礼制硬伤极多；女主号称大女主实则全程靠男主金手指降神解决问题；为虐而虐设计长嘴不解释的低幼误会；反派智商掉线，宅斗手段如同儿戏过家家。\"}" },
  { id: "genre_romance_campus", profileJson: "{\"positioning\":\"以高中或大学校园为背景，聚焦少年少女在学业压力与荷尔蒙萌动交织下的青涩初恋、自我觉醒与同伴羁绊，基调以清新治愈、酸甜拉扯与青春热血为主。\",\"sellingPoint\":\"极致细腻的暗恋与试探细节（校服衣角、前后桌传纸条、走廊偶遇的心跳）；打破工业糖精的纯粹感；少年人并肩作战对抗现实、共同考入理想学府的双向奔赴成长感。\",\"coreConflict\":\"懵懂的情感冲动与学校家庭规训（早恋禁忌、升学压力、阶层差异）之间的张力；对未来的迷茫分歧（文理分科、异地求学）与青春期敏感自尊心导致的试探与误解。\",\"readerExpectation\":\"高纯度的少女心与代入感；重温真实青春时光的怀旧滤镜；主角双方势均力敌、共同变好的正向情绪价值；告别成年人功利算计的真挚与孤勇。\",\"classicStructure\":\"开篇打破平衡（转学生/换同桌/军训结缘，迅速立住反差人设与微酸互动）；前期借由校园节点（月考、运动会、文艺晚会）推动情感暧昧升温；中期面临现实考验（文理分科、模考失利、家庭变故），在彼此扶持中完成心智成熟；后期以高考/毕业典礼为高潮，完成心意确认与顶峰相见的约定。\",\"worldSetting\":\"具有封闭感与生活气的校园空间：夏日风扇吱呀作响的教室、黄昏放学后的操场、晚自习透出灯光的教学楼、校门口文具店与小吃摊；受制于校规、模拟考排名与倒计时的现实规则。\",\"typicalCharacters\":\"男主多为清冷内敛的学神或桀骜不驯却唯独护短的少年；女主多为坚韧倔强的偏科少女或温吞细腻的观察者；标配搞怪助攻的死党、严厉但护短的班主任及提供安全感的闺蜜团。\",\"pacingAdvice\":\"以学期自然历法为时间轴，将日常小暧昧密集分布在前中期（3-5章设置一个眼神交汇或肢体微碰的心动高潮）；借模拟考、分科等事件形成阶段性压力波谷；高潮往往放在毕业或成人礼，拉满少年感的情感爆发。\",\"representativeWorks\":\"《最好的我们》、草莓印《偷偷藏不住》、橘生淮南《暗恋·橘生淮南》、耳东兔子《暗格里的秘密》、栖见《白日梦我》\",\"commonPitfalls\":\"完全悬浮脱离学生生活（全员逃课泡吧、对学业考试毫无敬畏心）；盲目复刻古早狗血疼痛文学（强加绝症、堕胎、家庭世仇等恶性误会）；男主油腻爹味或校园霸凌当深情；女主被降智为毫无个人目标与主见的恋爱挂件。\"}" },
  { id: "genre_game_root", profileJson: "{\"positioning\":\"以电子竞技赛事或虚拟网游竞技为核心舞台，围绕战局微操、战术博弈、战队组建及赛事征程展开的热血爽文，主打少年意气与夺冠信仰。\",\"sellingPoint\":\"极限微操的感官冲击与高光时刻、智商压制式的战术套路开发、绝境逆风翻盘的情绪爆发、弹幕解说及观众视角的多重视角震惊打脸、战队伙伴并肩作战的宿命热血。\",\"coreConflict\":\"赛场内微操反应、版本理解与团队协同的技术对抗；赛场外资本运作、假赛阴谋、年龄伤病及俱乐部内斗与纯粹电竞梦想之间的理念对抗。\",\"readerExpectation\":\"专业严谨且合乎逻辑的游戏机制设定，身临其境的赛场压迫感与决胜团战描写，队友各司其职且具备独立高光，以及最终斩获世界冠军登顶神坛的无上荣耀感。\",\"classicStructure\":\"开局多为老将遭背叛退役/天才民间高手被挖掘/重生带超前版本理解；前期从网吧赛或次级联赛起步，积累名气并聚拢个性鲜明的队友班底；中期征战顶级职业联赛，经历连胜、版本变动或战术被破的阵痛期完成蜕变；后期出征世界赛，鏖战宿命强敌，在万人瞩目下捧起奖杯。\",\"worldSetting\":\"以MOBA、FPS等成熟电竞类型或架空虚拟现实网游为规则底座，核心场景集中在俱乐部线下基地、排位高分段/天梯排行榜、万人体育馆总决赛舞台以及极具代入感的网络舆论场（赛事直播间、论坛贴吧）。\",\"typicalCharacters\":\"主角通常为大局观与微操兼备的战术大师或骚话天花板；队友涵盖稳健抗压老将、性格暴躁但执行力拉满的打手、极具灵性但心态不稳的新人；配角包括亦敌亦友的赛区宿敌、金句频出的专业解说与护短的俱乐部经理。\",\"pacingAdvice\":\"日常排位与直播打脸维持轻快幽默节奏（1-2章展现骚套路与弹幕互动），关键正赛需拉长战线、制造窒息张力（BO5赛制需多局铺垫，决胜局详写团战博弈）；爽点密度以小比赛提士气、关键赛打破质疑、洲际赛/世界赛迎来高潮阶梯式递进。\",\"representativeWorks\":\"《全职高手》、 《英雄联盟之谁与争锋》、 《联盟之魔王系统》、 《CSGO：这个狙击手有亿点强》、 《峡谷正能量》\",\"commonPitfalls\":\"战局描写沦为机械报技能与数值罗列导致缺乏画面感；主角个人英雄主义过重演变为单机游戏，弱化电竞团队协作灵魂；场外资本撕逼与恋爱狗血剧情喧宾夺主挤压赛场篇幅；严重违背竞技常识，让对手强行降智或通过明显破坏平衡的作弊系统取胜。\"}" },
  { id: "genre_game_esports", profileJson: "{\"positioning\":\"以真实或虚构竞技游戏为核心，聚焦职业选手从草根/低谷崛起、带领队伍征战联赛直至夺取世界总冠军的热血竞技小说。\",\"sellingPoint\":\"极致微操与战术博弈的临场爽感，绝境翻盘与打破偏见的打脸快感，伴随高燃赛场解说与弹幕互动的沉浸感，以及少年并肩逐梦的团队羁绊。\",\"coreConflict\":\"主角对胜利与冠军的执着追求，与外部阻碍（版本更迭、资本干扰、伤病与年龄、舆论唱衰、强敌战术克制）之间的激烈碰撞。\",\"readerExpectation\":\"专业可信的战术博弈与高光微操，绝境中个人英雄主义与团队配合的完美结合，纯粹不掺假的冠军荣耀，以及赛后全网吹捧的爽快反馈。\",\"classicStructure\":\"开局受挫或路人王登顶进入视野→网吧赛/次级联赛组建或融入新战队磨合→征战顶级常规赛打脸宿敌与豪门→季后赛/世界赛连战各路赛区风格强敌→决胜局极限绝杀登顶捧杯。\",\"worldSetting\":\"多基于MOBA（如英雄联盟/DOTA）或战术射击（如CS/瓦罗兰特）等规则清晰的竞技体系，场景涵盖训练基地、高分段天梯、赛后采访区以及万人欢呼的电竞体育馆。\",\"typicalCharacters\":\"主角（大心脏操作怪天才、重生/退役回归的战术大师）；配角（稳健抗压型队友、神经刀输出手、毒舌严厉的教练、擅长调动气氛的相声型解说、高傲但在赛场被击碎的对手明星选手）。\",\"pacingAdvice\":\"日常排位打脸与舆论铺垫占30%，赛事对抗与战术博弈占70%；小比赛快节奏带过（着重一两波关键团战），重要BO5需层层递进、底牌尽出，将情绪压到决胜局绝杀点彻底释放。\",\"representativeWorks\":\"《全职高手》、 《英雄联盟之谁与争锋》、 《联盟之魔王系统》、 《什么叫六边形打野啊》、 《联盟之开局成为电竞第一人》\",\"commonPitfalls\":\"游戏机制胡编乱造失去竞技逻辑；比赛过程流水账纯报技能名；恋爱戏份喧宾夺主将比赛沦为背景板；队友全员降智沦为主角个人的‘挂件’而丧失电竞团魂。\"}" },
  { id: "genre_game_online", profileJson: "{\"positioning\":\"以未来全息潜入式虚拟现实游戏为舞台，聚焦主角凭借超前理解、特殊天赋或顶尖操作崛起，横扫副本、制霸公会并引领全服格局的硬核游戏升级流小说。\",\"sellingPoint\":\"开荒副本与斩获首杀的全服通告震惊感；挖掘隐藏职业、神级装备与隐藏机制的探索爽感；凭借微操与战术跨级反杀财阀大公会的以弱胜强；游戏资产与影响力反哺现实的阶层跃升成就感。\",\"coreConflict\":\"草根散人高玩与垄断型资本大公会之间的资源争夺；阵营对抗、主城攻防与跨服务器国战的宏大博弈；深层世界观下游戏主脑觉醒、游戏现实重叠对现实秩序的冲击。\",\"readerExpectation\":\"严谨自洽的技能数值与职业平衡逻辑；智商在线的副本机制拆解与战术配合；每次全区通告带来的绝对打脸排面；主角梯队始终处于全服金字塔尖，拒绝辛苦成果被强权巧取豪夺。\",\"classicStructure\":\"开局抢占先机（重生先知/抽取唯一神级天赋/转职隐藏职业），新手村破纪录拿首杀立威；中期组建精英开荒团，垄断顶级团本通关攻略，建立公会硬刚老牌财团联盟；后期开启主城争夺与跨服国战，最终解密游戏世界的底层真相或实现虚实维度的彻底超脱。\",\"worldSetting\":\"硬件依赖神经链接全息舱或头盔；游戏内核多为西方奇幻、神魔史诗或东方玄幻，由高智能主脑自主运算推演，具备极高拟真度与无死角自由度；核心场景包括繁华主城拍卖行、暗流涌动的野外危险区、机制复杂的地下城副本与万人国战场地。\",\"typicalCharacters\":\"主角多为冷静果决的操作流独行侠、重回开服的老辣指挥官或冷门职业开发专家；固定队标配包含神级操作刺客死党、大局观出色的辅助奶妈、财力雄厚的精英白富美商人；反派涵盖仗势欺人的公会二世祖、操纵舆论与金价的资本巨鳄、阴险狠辣的职业赏金猎人。\",\"pacingAdvice\":\"3至5章完成一次单人奇遇或稀有怪击杀确立初期优势；15至20章引爆一次全服震惊的大型副本开荒或野外反围剿高潮；严格把控装备换代与技能进阶频率，形成“发现机制-破除垄断-首通公告-名利双收”的正向快节奏反馈闭环。\",\"representativeWorks\":\"《重生之贼行天下》、 《网游之近战法师》、 《猛龙过江》、 《全职高手》、 《斩月》\",\"commonPitfalls\":\"中后期数值光速膨胀，技能伤害动辄百千万导致操作博弈沦为纯数值对轰；现实线剧情过长且充斥狗血绑架、线下械斗，严重割裂游戏内主线节奏；副本流程如同流水账报技能参数，缺乏惊险的战术转折与智斗快感；为制造矛盾强行让全服玩家智商下线、公会会长无脑送人头。\"}" },
];

